"""Scope and ownership inventory. Planned rows do not advertise executable models."""

from dataclasses import dataclass
from typing import Literal

ModelStatus = Literal[
    "planned",
    "implemented_unverified",
    "implemented",
    "native_adapter_verified",
]
_MODEL_STATUSES = frozenset({
    "planned", "implemented_unverified", "implemented", "native_adapter_verified",
})


@dataclass(frozen=True, slots=True)
class ModelSpec:
    identifier: str
    purpose: str
    owner: str
    status: ModelStatus = "planned"
    evidence_needed: str = "Source-specific parameters and applicable independent observations"

    def __post_init__(self):
        if (not isinstance(self.identifier, str)
                or len(self.identifier.split(".")) != 2
                or any(not part or not part.isascii() or not part.replace("_", "").isalnum()
                       for part in self.identifier.split("."))):
            raise ValueError("Model identifiers use two simple dotted hierarchy components")
        for name in ("purpose", "owner", "evidence_needed"):
            value = getattr(self, name)
            if not isinstance(value, str) or not value.strip():
                raise ValueError(f"Model {name} must be declared as nonempty text")
        if not isinstance(self.status, str) or self.status not in _MODEL_STATUSES:
            raise ValueError(f"Unsupported model status: {self.status!r}")


