def model_catalog(*, family: str | None = None, status: ModelStatus | None = None) -> tuple[ModelSpec, ...]:
    identifiers = tuple(model.identifier for model in MODELS)
    if len(set(identifiers)) != len(identifiers):
        raise ValueError("Model family identifiers must be globally unique")
    if status is not None and (
        not isinstance(status, str) or status not in _MODEL_STATUSES
    ):
        raise ValueError(f"Unsupported model status filter: {status!r}")
    if family is not None and (
        not isinstance(family, str) or not family or "." in family
        or not family.isascii() or not family.replace("_", "").isalnum()
    ):
        raise ValueError("Family filters must be one simple hierarchy component")
    return tuple(model for model in MODELS
                 if (family is None or model.identifier.startswith(family + "."))
                 and (status is None or model.status == status))
